471  * Name: cam_dvp_gdma_isr
472  *
473  * GDMA RX channel interrupt: in_suc_eof fires once per frame (vs_eof=1,
474  * VSYNC-driven).  ISR does NOT touch NuttX semaphores/syslog (IRAM-safe):
475  * it increments a volatile counter and RE-ARMS the DMA chain at the frame
476  * boundary, exactly like the official driver's per-frame start_trans().
477  *
478  * Re-arm is DMA-only (stop -> in_rst -> reload link -> start), inline
479  * register writes so the ISR stays IRAM-safe.  We deliberately do NOT
480  * pulse cam_reset / cam_afifo_reset here: cam_reset would clear the
481  * LCD_CAM INT_ENA (debug log 2.29) and afifo_reset would drop FIFO
482  * continuity; the CAM peripheral keeps streaming on its own once started.
483  *
484  * This per-frame re-arm is the key fix for the "花色" (garbled colors):
485  * previously the chain was only re-armed from capture() at an arbitrary
486  * phase, so the DMA window [arm -> next VSYNC] was a partial frame that
487  * changed every capture.  Re-arming at every VSYNC EOF makes each window
488  * exactly one frame, aligned to the frame start.
489  ****************************************************************************/
490 
491 static int IRAM_ATTR cam_dvp_gdma_isr(int irq, void *context, void *arg)
492 {
493   struct esp32s3_cam_s *priv = &g_cam;
494   int ch = priv->dma_channel;
495   uint32_t st;
496   uint32_t regval;
497 
498   st = cam_dvp_getreg(cam_gdma_reg(DMA_IN_INT_ST_CH0_REG, ch));
499   if (st != 0)
500     {
501       cam_dvp_putreg(cam_gdma_reg(DMA_IN_INT_CLR_CH0_REG, ch), st);
502     }
503 
504   if (st & DMA_IN_SUC_EOF_CH0_INT_ST_M)
505     {
506       priv->block_done++;
507 
508       /* 1. stop DMA RX (self-clearing bit) */
509       regval = cam_dvp_getreg(cam_gdma_reg(DMA_IN_LINK_CH0_REG, ch));
510       regval |= DMA_INLINK_STOP_CH0_M;
511       cam_dvp_putreg(cam_gdma_reg(DMA_IN_LINK_CH0_REG, ch), regval);
512 
513       /* 2. reset RX FSM + FIFO pointer (in_rst pulse) */
514       regval = cam_dvp_getreg(cam_gdma_reg(DMA_IN_CONF0_CH0_REG, ch));
515       regval |= DMA_IN_RST_CH0_M;
516       cam_dvp_putreg(cam_gdma_reg(DMA_IN_CONF0_CH0_REG, ch), regval);
517       regval &= ~DMA_IN_RST_CH0_M;
518       cam_dvp_putreg(cam_gdma_reg(DMA_IN_CONF0_CH0_REG, ch), regval);
519 
520       /* 3. reload the descriptor link base (preserve other LINK bits) */
521       regval = cam_dvp_getreg(cam_gdma_reg(DMA_IN_LINK_CH0_REG, ch));
