/****************************************************************************
 * 高光溢出自适应（2026-09-10 用户报"色彩有粉色的色块失真"）
 *
 * 现象：画面亮部（窗/灯）整片糊成粉/品红色块、没有层次。
 *
 * 板卡实测根因（md_395f676e26a5 原始 565 逐通道拆解）：
 *   - 粉色区里 R 通道 54% 的像素已经顶到 31/31，而 G 一个都没满、B 只满 8%
 *     → "红先撞顶、绿还有富余" = 品红；那片区域因此失去全部细节。
 *   - 传感器 AWB 增益 R=1.63× / G=1.00× / B=1.18×（0x3400=0x0688、
 *     0x3402=0x0400、0x3404=0x04bd），即绿色只要亮过满量程的 61%，
 *     红色就已经溢出 —— 这是"粉色"的直接来源。
 *   - 0x3500-02 读出曝光 = 0x310 = 784 行 ≥ 总行数 783（顶格）：房间偏暗，
 *     AEC 把曝光拉满提亮暗部，亮部必然过曝。
 *
 * 对策：拍完立刻量一遍"红通道撞顶"的比例；超标就下调 AEC 曝光目标
 * （0x3a0f/0x3a10/0x3a1b/0x3a1e）再拍一帧，最多 3 帧。只在高光溢出时
 * 才降曝光 —— 正常场景完全不受影响（全局降曝光会把本来不亮的画面压更暗）。
 ****************************************************************************/

#define CAM_AE_HIGH_DEF      48   /* 0x3a0f 默认目标上限（官方序列值 0x30） */
#define CAM_AE_LOW_DEF       40   /* 0x3a10 默认目标下限（0x28） */
#define CAM_AE_STEP           8   /* 每次下调的档位 */
#define CAM_HL_MAX_TRIES      3   /* 最多拍 3 帧（默认 + 2 次降档） */
#define CAM_HL_CLIP_LIMIT_PM 15   /* 可接受的红撞顶比例（千分之） */
#define CAM_HL_MIN_LUMA       70  /* 画面均值低于此值不再降曝光（本来就不亮） */
#define CAM_HL_WAIT_MS      400   /* 降档后等 AEC 收敛 */

/* 设置 AEC/AWB 曝光目标：high/low 与官方 set_ae_level 同构
 * （fast_low = low>>1、fast_high = high<<1） */

static int ov3660_set_ae_target(uint8_t high, uint8_t low)
{
  return board_camera_sccb_write(0x3a0f, high)
      || board_camera_sccb_write(0x3a10, low)
      || board_camera_sccb_write(0x3a1b, high)
      || board_camera_sccb_write(0x3a1e, low)
      || board_camera_sccb_write(0x3a11, (uint8_t)(high << 1))
      || board_camera_sccb_write(0x3a1f, (uint8_t)(low >> 1));
}

/* 千分比：红通道顶格（R5=31 → R8≥248）的像素占比 */

static unsigned cam_frame_red_clip_permille(const uint8_t *fb, size_t nbytes)
{
  unsigned n = (unsigned)(nbytes / 2);
  unsigned i;
  unsigned clip = 0;

  if (n == 0)
    {
      return 0;
    }

  for (i = 0; i < n; i++)
    {
      uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
      if (((px >> 11) & 0x1f) == 0x1f)
        {
          clip++;
        }
    }

  return (unsigned)(((uint32_t)clip * 1000U) / n);
}

/* 画面平均亮度（0-255，每 64 像素抽 1 个，够判"是不是本来就很暗"） */

static unsigned cam_frame_mean_luma(const uint8_t *fb, size_t nbytes)
{
  unsigned n = (unsigned)(nbytes / 2);
  unsigned i;
  uint32_t sum = 0;
  unsigned cnt = 0;

  for (i = 0; i < n; i += 64)
    {
      uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
      unsigned r = ((px >> 11) & 0x1f) * 255U / 31U;
      unsigned g = ((px >> 5) & 0x3f) * 255U / 63U;
      unsigned b = (px & 0x1f) * 255U / 31U;
      sum += (r + g + b) / 3U;
      cnt++;
    }

  return cnt ? (unsigned)(sum / cnt) : 0;
}
