int camera_photo_capture(const uint8_t **frame, size_t *len_out)
{
  size_t total = 0;
  unsigned clip = 0;
  int ret;
  int attempt;
  uint8_t ae_hi = CAM_AE_HIGH_DEF;
  uint8_t ae_lo = CAM_AE_LOW_DEF;
  bool lowered = false;

  if (frame == NULL || len_out == NULL)
    {
      return -EINVAL;
