  *frame = NULL;
  *len_out = 0;

  ret = esp32s3_cam_dvp_init();
  if (ret < 0)
    {
      printf("[Cam] photo: dvp init failed %d\n", ret);
      return ret;
    }

  for (attempt = 0; attempt < CAM_HL_MAX_TRIES; attempt++)
    {
      if (attempt > 0)
        {
          ae_hi = (uint8_t)(ae_hi - CAM_AE_STEP);
          ae_lo = (uint8_t)(ae_lo - CAM_AE_STEP);
          ov3660_set_ae_target(ae_hi, ae_lo);
          lowered = true;
          printf("[Cam] photo: 亮部过曝，AEC 目标降到 %u/%u，重拍第 %d 张\n",
                 (unsigned)ae_hi, (unsigned)ae_lo, attempt + 1);
          usleep(CAM_HL_WAIT_MS * 1000);
        }

      ret = cam_photo_capture_once(&total);
      if (ret < 0)
        {
          if (lowered)
            {
              ov3660_set_ae_target(CAM_AE_HIGH_DEF, CAM_AE_LOW_DEF);
