          return ret;
        }

      clip = cam_frame_red_clip_permille(esp32s3_cam_dvp_get_frame(), total);
      printf("[Cam] photo #%d: 红通道过曝 %.1f%% (阈值 %.1f%%)\n",
             attempt + 1, (double)clip / 10.0,
             (double)CAM_HL_CLIP_LIMIT_PM / 10.0);

      if (clip <= CAM_HL_CLIP_LIMIT_PM)
        {
