        }

      if (attempt + 1 < CAM_HL_MAX_TRIES &&
          cam_frame_mean_luma(esp32s3_cam_dvp_get_frame(), total) <
          CAM_HL_MIN_LUMA)
        {
          printf("[Cam] photo: 画面本已偏暗，不再降曝光\n");
          break;
        }
    }

  /* 恢复默认曝光目标：预览/下一次拍照仍按原亮度收敛 */

  if (lowered)
    {
      ov3660_set_ae_target(CAM_AE_HIGH_DEF, CAM_AE_LOW_DEF);
    }

  *frame = esp32s3_cam_dvp_get_frame();
  *len_out = total;

  printf("[Cam] photo captured: %u bytes (%dx%d)\n",
         (unsigned)total, CAM_PHOTO_W, CAM_PHOTO_H);
  return 0;
}
