void cam_highlight_desat(uint8_t *fb, unsigned npx)
{
  unsigned i;

  for (i = 0; i < npx; i++)
    {
      uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
      unsigned r = ((px >> 11) & 0x1f);
      unsigned g = ((px >> 5) & 0x3f);
      unsigned b = (px & 0x1f);
      unsigned r6 = (r << 1) | (r >> 4);   /* 5bit -> 6bit（位复制） */
      unsigned b6 = (b << 1) | (b >> 4);
      unsigned mx = r6 > g ? r6 : g;
      unsigned k;

      if (b6 > mx)
        {
          mx = b6;
        }

      if (mx <= CAM_HL_DESAT_T6)
        {
          continue;
        }

      /* 越接近满量程拉得越狠：mx=T6 时不动，mx=63 时完全去饱和 */

      k = (mx - CAM_HL_DESAT_T6) * 255u / (63u - CAM_HL_DESAT_T6);

      r6 += (mx - r6) * k / 255u;
      g  += (mx - g) * k / 255u;
      b6 += (mx - b6) * k / 255u;

      r = (r6 + 1) >> 1;                   /* 6bit -> 5bit */
      b = (b6 + 1) >> 1;
      if (r > 31) r = 31;
      if (g > 63) g = 63;
      if (b > 31) b = 31;

      px = (uint16_t)((r << 11) | (g << 5) | b);
      fb[i * 2] = (uint8_t)(px & 0xff);
      fb[i * 2 + 1] = (uint8_t)(px >> 8);
    }
}
```

