#define CAM_AE_LOW_DEF       40   /* 0x3a10 默认目标下限（0x28） */
#define CAM_AE_STEP           8   /* 每次下调的档位 */
#define CAM_HL_MAX_TRIES      3   /* 最多拍 3 帧（默认 + 2 次降档） */
#define CAM_HL_CLIP_LIMIT_PM 15   /* 可接受的红撞顶比例（千分之，1.5%） */
