 ****************************************************************************/

int camera_photo_capture(const uint8_t **frame, size_t *len_out)
{
  size_t total = 0;
  uint8_t *fb;
  unsigned clip;
  int ret;

  if (frame == NULL || len_out == NULL)
    {
      return -EINVAL;
    }

  *frame = NULL;
  *len_out = 0;

  ret = esp32s3_cam_dvp_init();
  if (ret < 0)
    {
      printf("[Cam] photo: dvp init failed %d\n", ret);
      return ret;
    }

