         (double)clip / 10.0, cam_frame_mean_luma(fb, total));

  cam_highlight_desat(fb, (unsigned)(total / 2));

  *frame = fb;
  *len_out = total;

  printf("[Cam] photo captured: %u bytes (%dx%d)\n",
         (unsigned)total, CAM_PHOTO_W, CAM_PHOTO_H);
  return 0;
}

