 1390:  *   只会把整张照片一起压暗，AI 反而更看不清。方向错了。
 1391:  *
 1392:  * 对策：拍完做一次【高光去饱和】（ISP 处理这类"品红高光"的通用做法）：
 1393:  *   对接近满量程的像素按比例把它拉向最亮通道 —— 越接近满量程拉得越狠，
 1394:  *   粉色块 → 中性白色高光；中间调与暗部一个像素都不动。
 1395: ****************************************************************************/
 1396: 
 1397: #define CAM_HL_DESAT_T6      55   /* 6bit 域的起拉阈值（55/63≈87% 亮度） */
 1398: 
 1399: /* 高光去饱和：把"红通道先撞顶"造成的粉色块还原成中性高光。
 1400:  * 全整数、就地改帧；中间调用不起作用（亮度没到阈值直接跳过）。 */
 1401: 
 1402: void cam_highlight_desat(uint8_t *fb, unsigned npx)
 1403: {
 1404:   unsigned i;
 1405: 
 1406:   for (i = 0; i < npx; i++)
 1407:     {
 1408:       uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
 1409:       unsigned r = (px >> 11) & 0x1f;
 1410:       unsigned g = (px >> 5) & 0x3f;
 1411:       unsigned b = px & 0x1f;
 1412:       unsigned r6 = (r << 1) | (r >> 4);   /* 5bit -> 6bit（位复制） */
 1413:       unsigned b6 = (b << 1) | (b >> 4);
 1414:       unsigned mx = r6 > g ? r6 : g;
 1415:       unsigned k;
 1416: 
 1417:       if (b6 > mx)
 1418:         {
 1419:           mx = b6;
 1420:         }
 1421: 
 1422:       if (mx <= CAM_HL_DESAT_T6)
 1423:         {
 1424:           continue;                        /* 正常亮度：原样 */
 1425:         }
 1426: 
 1427:       /* 越接近满量程拉得越狠：mx=T6 不动，mx=63 完全去饱和 */
 1428: 
 1429:       k = (mx - CAM_HL_DESAT_T6) * 255u / (63u - CAM_HL_DESAT_T6);
 1430: 
 1431:       r6 += (mx - r6) * k / 255u;
 1432:       g  += (mx - g) * k / 255u;
 1433:       b6 += (mx - b6) * k / 255u;
 1434: 
 1435:       r = (r6 + 1) >> 1;                   /* 6bit -> 5bit */
 1436:       b = (b6 + 1) >> 1;
 1437: 
 1438:       if (r > 31) r = 31;
 1439:       if (g > 63) g = 63;
 1440:       if (b > 31) b = 31;
 1441: 
 1442:       px = (uint16_t)((r << 11) | (g << 5) | b);
 1443:       fb[i * 2] = (uint8_t)(px & 0xff);
 1444:       fb[i * 2 + 1] = (uint8_t)(px >> 8);
 1445:     }
 1446: }
