 1450: static unsigned cam_frame_red_clip_permille(const uint8_t *fb, size_t nbytes)
 1451: {
 1452:   unsigned n = (unsigned)(nbytes / 2);
 1453:   unsigned i;
 1454:   unsigned clip = 0;
 1455: 
 1456:   if (n == 0)
 1457:     {
 1458:       return 0;
 1459:     }
 1460: 
 1461:   for (i = 0; i < n; i++)
 1462:     {
 1463:       uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
 1464:       if (((px >> 11) & 0x1f) == 0x1f)
 1465:         {
 1466:           clip++;
 1467:         }
 1468:     }
 1469: 
 1470:   return (unsigned)(((uint32_t)clip * 1000U) / n);
 1471: }
