 1474: 
 1475: static unsigned cam_frame_mean_luma(const uint8_t *fb, size_t nbytes)
 1476: {
 1477:   unsigned n = (unsigned)(nbytes / 2);
 1478:   unsigned i;
 1479:   uint32_t sum = 0;
 1480:   unsigned cnt = 0;
 1481: 
 1482:   for (i = 0; i < n; i += 64)
 1483:     {
 1484:       uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
 1485:       unsigned r = (((px >> 11) & 0x1f) * 255U) / 31U;
 1486:       unsigned g = (((px >> 5) & 0x3f) * 255U) / 63U;
 1487:       unsigned b = ((px & 0x1f) * 255U) / 31U;
 1488:       sum += (r + g + b) / 3U;
 1489:       cnt++;
 1490:     }
 1491: 
 1492:   return cnt ? (unsigned)(sum / cnt) : 0;
 1493: }
