  31:       static unsigned s_fail_cnt;
  32: 
  33:       if (s_fail_cnt++ == 0)
  34:         {
  35:           HAL_LOGE("batt", "open %s failed: %d (cnt=%u)",
  36:                    ADC_DEV, errno, s_fail_cnt);
  37:         }
  38: 
  39:       return -errno;
  40:     }
  41: 
  42:   int ret = ioctl(fd, ANIOC_TRIGGER, 0);
  43:   if (ret < 0)
  44:     {
  45:       HAL_LOGE("batt", "ioctl ANIOC_TRIGGER failed: %d", errno);
  46:       close(fd);
  47:       return -errno;
  48:     }
  49: 
  50:   struct adc_msg_s sample;
  51:   ret = read(fd, &sample, sizeof(sample));
  52:   close(fd);
  53: 
  54:   if (ret < 0)
  55:     {
  56:       HAL_LOGE("batt", "read failed: %d", errno);
  57:       return -errno;
  58:     }
