/* 千分比：粉色/品红高光嫌疑（去饱和的正面指标）
 *
 * ⚠️ 2026-09-10 教训：一开始想用"红通道顶格(R5=31)"来衡量去饱和有没有生效，
 * 结果恒为"没生效" —— 去饱和按设计是把粉色【拉成白色】，红通道仍然是满的
 * （G/B 一起被拉上来），顶格率当然不降。之前"6 次里 2 次没进上传帧"就是
 * 这个错指标得出的假结论。
 *
 * 正确口径：品红 = 亮（红接近满量程）+ 红明显高于绿。去饱和做完这类像素
 * 应该基本消失（变成中性白）。 */
static unsigned cam_frame_pink_permille(const uint8_t *fb, size_t nbytes)
{
  unsigned n = (unsigned)(nbytes / 2);
  unsigned i;
  unsigned pink = 0;

  if (n == 0) return 0;

  for (i = 0; i < n; i++)
    {
      uint16_t px = (uint16_t)(fb[i * 2] | (fb[i * 2 + 1] << 8));
      unsigned r6 = (((px >> 11) & 0x1f) << 1) | (px >> 15);
      unsigned g6 = (px >> 5) & 0x3f;

      if (r6 >= 56 && (r6 - g6) >= 10)
        {
          pink++;
        }
    }

  return (unsigned)(((uint32_t)pink * 1000U) / n);
}
