 555:   if (p[0] < 0x80)
 556:     {
 557:       *len = 1;
 558:       return p[0];
 559:     }
 560: 
 561:   if ((p[0] & 0xe0) == 0xc0 && (p[1] & 0xc0) == 0x80)
 562:     {
 563:       *len = 2;
 564:       return ((uint32_t)(p[0] & 0x1f) << 6) | (p[1] & 0x3f);
 565:     }
 566: 
 567:   if ((p[0] & 0xf0) == 0xe0 && (p[1] & 0xc0) == 0x80 && (p[2] & 0xc0) == 0x80)
 568:     {
 569:       *len = 3;
 570:       return ((uint32_t)(p[0] & 0x0f) << 12) |
 571:              ((uint32_t)(p[1] & 0x3f) << 6) | (p[2] & 0x3f);
 572:     }
 573: 
 574:   if ((p[0] & 0xf8) == 0xf0 && (p[1] & 0xc0) == 0x80 &&
 575:       (p[2] & 0xc0) == 0x80 && (p[3] & 0xc0) == 0x80)
