         (int)g_src, (void *)s_main20.fallback, (void *)s_sd_lvfont20.fallback,
         (void *)s_sd_lvfont20.user_data, (void *)f->fp,
         (unsigned)f->count, (unsigned)f->idx_off);

  if (f->fp == NULL)
    {
      printf("[Diag] fp 为空，SD 兜底不可用\n");
      return;
    }

  while (lo < hi && step < 32)
    {
      uint32_t mid = (lo + hi) / 2;
      uint32_t u;
      long off = ZH_SD_HEADER + (long)mid * ZH_SD_IDX_ENTRY;
      int rc;

      errno = 0;
      rc = fseek(f->fp, off, SEEK_SET);
      int er1 = errno;
      size_t rd = fread(b, 1, ZH_SD_IDX_ENTRY, f->fp);
      int er2 = errno;
      u = (uint32_t)b[0] | ((uint32_t)b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
      printf("[Diag] step%2d mid=%u off=%ld u=%04X(%lu) fseek_rc=%d e1=%d rd=%u e2=%d\n",
             step, (unsigned)mid, off, (unsigned)u, (unsigned long)u, rc, er1,
             (unsigned)rd, er2);
      step++;

      if (u < cp) lo = mid + 1;
      else if (u > cp) hi = mid;
      else break;
    }

  memset(&dsc, 0, sizeof(dsc));
  ok = lv_font_get_glyph_dsc(&s_main20, &dsc, cp, 0);
  printf("[Diag] U+%04X lv_font_get_glyph_dsc(20px)=%d ph=%d resolved=%p box=%dx%d adv=%u\n",
