void zh_font_diag_sd(uint32_t cp)
{
  zh_sd_font_t *f = &s_sd_font20;
  lv_font_glyph_dsc_t dsc;
  uint8_t b[ZH_SD_IDX_ENTRY];
  uint32_t lo = 0;
  uint32_t hi = f->count;
