  printf("[Diag] src=%d main20.fb=%p sd20.fb=%p ud=%p fp=%p count=%u idx_off=%u\n",
         (int)g_src, (void *)s_main20.fallback, (void *)s_sd_lvfont20.fallback,
         (void *)s_sd_lvfont20.user_data, (void *)f->fp, (unsigned)f->count,
         (unsigned)f->idx_off);

