    }
  else
    {
      while (lo < hi && step < 20)
        {
          uint32_t mid = (lo + hi) / 2;
          long off = (long)ZH_SD_HEADER + (long)mid * ZH_SD_IDX_ENTRY;
          uint32_t u;
          int rc1;
          int e1;
          int e2;
          size_t rd;

          errno = 0;
          rc1 = fseek(f->fp, off, SEEK_SET);
          e1 = errno;
          errno = 0;
          rd = fread(b, 1, ZH_SD_IDX_ENTRY, f->fp);
          e2 = errno;

          u = (uint32_t)b[0] | ((uint32_t)b[1] << 8) |
              ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);

          printf("[Diag] #%d mid=%u off=%ld fseek=%d(e=%d) fread=%u(e=%d) u=%04X\n",
                 step, (unsigned)mid, off, rc1, e1, (unsigned)rd, e2,
                 (unsigned)u);
          step++;

          if (u < cp)
            {
              lo = mid + 1;
            }
          else if (u > cp)
            {
              hi = mid;
            }
          else
            {
              break;
            }
        }
    }

  memset(&dsc, 0, sizeof(dsc));
  printf("[Diag] U+%04X 20px整体链=%d ph=%d resolved=%p\n", (unsigned)cp,
         (int)lv_font_get_glyph_dsc(&s_main20, &dsc, cp, 0),
