int sd_card_status(void)
{
  struct statfs buf;

  /* statfs on a mounted vfat returns MSDOS_SUPER_MAGIC; on a plain rootfs
   * directory it returns the rootfs type. That distinguishes "mounted"
   * from "not mounted". */

  if (statfs(SD_MOUNTPOINT, &buf) < 0)
