'''/* 读一段字节；失败（句柄失效/IO 错）则关旧开新重试一次，成功返回 true。
 * 自愈点：NuttX fd 表按任务隔离，句柄被别的任务"用坏"或驱动重挂后，
 * 这里重开即恢复，不会永久降级成方框。 */

static bool zh_sd_read_at(zh_sd_font_t *f, uint32_t off, void *buf, size_t n)
{
  int tries;

  for (tries = 0; tries < 2; tries++)
    {
      if (f->fp != NULL && fseek(f->fp, (long)off, SEEK_SET) == 0 &&
          fread(buf, 1, n, f->fp) == n)
        {
          return true;
        }

      if (tries > 0)
        {
          break;
        }

      if (f->size_px == 0 || zh_sd_open_one(f, f->size_px) != 0)
        {
          f->m_unicode = 0;   /* 句柄不可用：清 memo，禁止幽灵字形 */

          if (s_sd_reopen_fail++ == 0)
            {
              printf("[Font] SD 字库句柄失效且重开失败 errno=%d（%dpx）\\n",
                     errno, f->size_px);
            }

          return false;
        }

      if (s_sd_reopen_ok++ == 0)
        {
          printf("[Font] SD 字库句柄失效 -> 已自动重开（%dpx，自愈）\\n",
                 f->size_px);
        }
    }

  return false;
}

static void zh_sd_close(void)
