def cps_of(path):
    src = io.open(path, encoding="utf-8").read()
    cmaps = re.search(r"lv_font_fmt_txt_cmap_t cmaps\[\]\s*=\s*\{(.*?)\n\};", src, re.S)
    blk = cmaps.group(1)
    out = set()
    # 每个 cmap 条目
    for entry in re.finditer(r"\.range_start\s*=\s*(0x[0-9a-fA-F]+|\d+)\s*,\s*\.range_length\s*=\s*(0x[0-9a-fA-F]+|\d+)\s*,\s*\.glyph_id_start\s*=\s*(0x[0-9a-fA-F]+|\d+)\s*,\s*\.unicode_list\s*=\s*(\w+|NULL)", blk):
        rs = int(entry.group(1), 0); rl = int(entry.group(2), 0); ul = entry.group(4)
        if ul == "NULL":
            out |= set(range(rs, rs + rl))
        else:
            m = re.search(r"static const uint16_t %s\[\]\s*=\s*\{(.*?)\};" % ul, src, re.S)
            vals = [int(x,0) for x in re.findall(r"0x[0-9a-fA-F]+|\d+", m.group(1))]
            out |= {rs + v for v in vals}
    return out

