Implementation:

```c
/* 把 src 拷贝到 dst（最多 cap-1 字节 + '\0'），规则：
 *   - 控制字符（<0x20）打印成 '.'，避免日志里换行把一条记录冲散；
 *   - 只在完整 UTF-8 字符边界上截断，绝不切出半个汉字
 *     （以前固定 72 字节，长行被砍在汉字中间，日志里就是 "它�" 这种假乱码）。
 * 返回写入字节数。 */

static int ui_utf8_copy_safe(char *dst, int cap, const char *src)
{
  const unsigned char *s = (const unsigned char *)src;
  int n = 0;

  if (dst == NULL || cap <= 0)
    {
      return 0;
    }

  while (*s != '\0')
    {
      int len = 1;

      if ((s[0] & 0xe0) == 0xc0) len = 2;
      else if ((s[0] & 0xf0) == 0xe0) len = 3;
      else if ((s[0] & 0xf8) == 0xf0) len = 4;

      /* 后续字节必须是 10xxxxxx，否则当成单字节坏数据 */
      for (int i = 1; i < len; i++)
        {
          if ((s[i] & 0xc0) != 0x80) { len = 1; break; }
        }

      if (n + len > cap - 1) break;

      if (len == 1)
        {
          dst[n++] = (s[0] >= 0x20) ? (char)s[0] : '.';
        }
      else
        {
          for (int i = 0; i < len; i++) dst[n++] = (char)s[i];
        }

      s += len;
    }

  dst[n] = '\0';
  return n;
}
```

