 * apps/plant-companion/ui/widgets/widget_bottomnav.c
 *
 * 4-Tab 底部导航：🏠 首页 / 📊 数据 / ✅ 任务 / 📖 日记
 * 每个 Tab = 纵向 (图标+文字) 按钮，选中时主题色高亮
 *
 * 图标占位说明（LVGL v9 montserrat_20 内置字形，均验证存在）：
 *   首页 = LV_SYMBOL_HOME(0xF015) 数据 = LV_SYMBOL_BARS(0xF0C9 柱状图)
 *   任务 = LV_SYMBOL_LIST(0xF00B) 日记 = LV_SYMBOL_EDIT(0xF304 铅笔=书写)
 * 注意：LV_SYMBOL_BOOKMARK(0xF02D) 不在 montserrat_20，勿用。
 ****************************************************************************/

#include <lvgl/lvgl.h>
#include <string.h>
#include <stdio.h>

#include "widget_bottomnav.h"
#include "../theme/theme_plant.h"

#define NAV_ICON_HOME   LV_SYMBOL_HOME
#define NAV_ICON_DATA   LV_SYMBOL_BARS
#define NAV_ICON_TASKS  LV_SYMBOL_LIST
#define NAV_ICON_DIARY  LV_SYMBOL_EDIT

#define NAV_TAB_COUNT   PLANT_TAB_COUNT

static const char *const nav_icons[NAV_TAB_COUNT] =
{
  NAV_ICON_HOME, NAV_ICON_DATA, NAV_ICON_TASKS, NAV_ICON_DIARY
};

static const char *const nav_labels[NAV_TAB_COUNT] =
{
  "首页", "数据", "任务", "日记"
};

/* 回调上下文，存在导航栏 user_data 里 */

struct nav_ctx_s
{
  plant_nav_cb_t cb;
  void *user_data;
  lv_obj_t *tabs[NAV_TAB_COUNT];
  int active;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void nav_on_click(lv_event_t *e)
{
  lv_obj_t *tab = lv_event_get_target(e);
  struct nav_ctx_s *ctx = (struct nav_ctx_s *)lv_obj_get_user_data(
                             lv_obj_get_parent(tab));
  int tab_id = (int)(intptr_t)lv_obj_get_user_data(tab);

  if (ctx == NULL)
    {
      return;
    }

  if (ctx->active != tab_id)
    {
      ctx->active = tab_id;
      widget_bottomnav_set_active(lv_obj_get_parent(tab), tab_id);

      if (ctx->cb != NULL)
        {
          ctx->cb(ctx->user_data, tab_id);
        }
    }
}

/* 页面删除时释放 nav_ctx_s —— 否则每次建页 lv_malloc 的 ctx 会泄漏
 * （LVGL 不会自动释放 user_data），长期切 Tab 会耗尽 LVGL 池 → 黑屏。 */

static void nav_on_delete(lv_event_t *e)
{
  struct nav_ctx_s *ctx = (struct nav_ctx_s *)lv_event_get_user_data(e);

  if (ctx != NULL)
    {
      lv_free(ctx);
    }
}

static void nav_set_tab_style(lv_obj_t *tab, bool active)
{
  if (active)
    {
      lv_obj_set_style_bg_color(tab, lv_color_hex(TP_CLR_NAV_ACTIVE), 0);
      lv_obj_set_style_bg_opa(tab, LV_OPA_COVER, 0);
      lv_obj_set_style_text_color(tab, lv_color_hex(TP_CLR_TEXT_ON_PRIMARY), 0);
    }
  else
    {
      lv_obj_set_style_bg_color(tab, lv_color_hex(TP_CLR_NAV_BG), 0);
      lv_obj_set_style_bg_opa(tab, LV_OPA_TRANSP, 0);
      lv_obj_set_style_text_color(tab, lv_color_hex(TP_CLR_NAV_INACTIVE), 0);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

lv_obj_t *widget_bottomnav_create(lv_obj_t *parent,
                                  plant_nav_cb_t cb, void *user_data)
{
  struct nav_ctx_s *ctx;
  lv_obj_t *nav;
  int i;

  ctx = (struct nav_ctx_s *)lv_malloc(sizeof(struct nav_ctx_s));
  if (ctx == NULL)
    {
      printf("[Nav] lv_malloc ctx FAILED\n");
      return NULL;
    }

  memset(ctx, 0, sizeof(*ctx));
  ctx->cb = cb;
  ctx->user_data = user_data;
  ctx->active = PLANT_TAB_HOME;

  nav = lv_obj_create(parent);
  lv_obj_remove_style_all(nav);
  lv_obj_set_size(nav, LV_PCT(100), TP_NAV_BAR_H);
  lv_obj_set_pos(nav, 0, 320 - TP_NAV_BAR_H);
  lv_obj_set_style_bg_color(nav, lv_color_hex(TP_CLR_NAV_BG), 0);
  lv_obj_set_style_bg_opa(nav, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(nav, 1, 0);
  lv_obj_set_style_border_color(nav, lv_color_hex(0xe5e7eb), 0);
  lv_obj_set_style_border_side(nav, LV_BORDER_SIDE_TOP, 0);
  lv_obj_set_user_data(nav, ctx);

  /* 释放钩子：页面删除时回收 ctx（防 LVGL 池泄漏） */

  lv_obj_add_event_cb(nav, nav_on_delete, LV_EVENT_DELETE, ctx);

  /* flex 横向均分 4 Tab */

  lv_obj_set_flex_flow(nav, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(nav, LV_FLEX_ALIGN_SPACE_EVENLY, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER);

  for (i = 0; i < NAV_TAB_COUNT; i++)
    {
      lv_obj_t *tab = lv_obj_create(nav);
      lv_obj_t *icon;
      lv_obj_t *label;

      lv_obj_remove_style_all(tab);
      lv_obj_set_size(tab, 90, TP_NAV_BAR_H);
      lv_obj_set_style_radius(tab, 0, 0);
      lv_obj_set_user_data(tab, (void *)(intptr_t)i);

      /* 纵向 flex：图标在上，文字在下 */

      lv_obj_set_flex_flow(tab, LV_FLEX_FLOW_COLUMN);
      lv_obj_set_flex_align(tab, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
                            LV_FLEX_ALIGN_CENTER);
      lv_obj_set_style_pad_row(tab, 2, 0);

      icon = lv_label_create(tab);
      lv_label_set_text(icon, nav_icons[i]);
      lv_obj_set_style_text_font(icon, &lv_font_montserrat_20, 0);

      label = lv_label_create(tab);
      lv_label_set_text(label, nav_labels[i]);
      lv_obj_set_style_text_font(label, TP_FONT_BODY, 0);

      nav_set_tab_style(tab, (i == ctx->active));

      lv_obj_add_event_cb(tab, nav_on_click, LV_EVENT_CLICKED, NULL);

      ctx->tabs[i] = tab;
    }

  return nav;
}

void widget_bottomnav_set_active(lv_obj_t *nav, int tab_id)
{
  struct nav_ctx_s *ctx = (struct nav_ctx_s *)lv_obj_get_user_data(nav);
  int i;

  if (ctx == NULL || tab_id < 0 || tab_id >= NAV_TAB_COUNT)
    {
      return;
    }

  ctx->active = tab_id;

  for (i = 0; i < NAV_TAB_COUNT; i++)
    {
      nav_set_tab_style(ctx->tabs[i], (i == tab_id));
    }
}

int widget_bottomnav_get_active(lv_obj_t *nav)
{
  struct nav_ctx_s *ctx = (struct nav_ctx_s *)lv_obj_get_user_data(nav);

  return (ctx != NULL) ? ctx->active : PLANT_TAB_HOME;
}

lv_obj_t *widget_bottomnav_find(lv_obj_t *screen)
{
  uint32_t i;
  uint32_t cnt;

  if (screen == NULL)
    {
      return NULL;
    }

  cnt = lv_obj_get_child_count(screen);

  for (i = 0; i < cnt; i++)
    {
      lv_obj_t *child = lv_obj_get_child(screen, i);

      if (lv_obj_get_parent(child) != screen)
        {
          continue;
        }

      /* 底部导航几何特征：全宽 480、高 TP_NAV_BAR_H、底边贴屏底。
       * （避免解引用任意 child 的 user_data——Tab 按钮的 user_data 是
       * 0..3 的小整数，当指针用会段错误。） */

      if (lv_obj_get_width(child) == 480 &&
          lv_obj_get_height(child) == TP_NAV_BAR_H &&
          lv_obj_get_y(child) + lv_obj_get_height(child) == 320)
        {
          struct nav_ctx_s *ctx;

          ctx = (struct nav_ctx_s *)lv_obj_get_user_data(child);
          if (ctx != NULL && ctx->cb != NULL)
            {
              return child;
            }
        }
    }

  return NULL;
}

bool widget_bottomnav_tab_center(lv_obj_t *nav, int tab_id,
                                 int *cx, int *cy)
{
  struct nav_ctx_s *ctx;
  lv_obj_t *tab;
  lv_obj_t *o;
  int x = 0;
  int y = 0;

  if (nav == NULL)
    {
      return false;
    }

  ctx = (struct nav_ctx_s *)lv_obj_get_user_data(nav);
  if (ctx == NULL || tab_id < 0 || tab_id >= NAV_TAB_COUNT)
    {
      return false;
    }

  tab = ctx->tabs[tab_id];
  if (tab == NULL)
    {
      return false;
    }

  for (o = tab; o != NULL; o = lv_obj_get_parent(o))
    {
      x += lv_obj_get_x(o);
      y += lv_obj_get_y(o);
    }

  if (cx != NULL)
    {
      *cx = x + lv_obj_get_width(tab) / 2;
    }

  if (cy != NULL)
    {
      *cy = y + lv_obj_get_height(tab) / 2;
    }

  return true;
}

