void screen_home_refresh(int health, int moisture, int temp, int light, int ec)
{
  char buf[16];

  if (s_arc != NULL && s_arc_value != NULL)
    {
      lv_arc_set_value(s_arc, health);
      snprintf(buf, sizeof(buf), "%d", health);
      lv_label_set_text(s_arc_value, buf);
    }

  if (s_moisture != NULL)
    {
      snprintf(buf, sizeof(buf), "%d%%", moisture);
      lv_label_set_text(s_moisture, buf);
    }

  if (s_temp != NULL)
    {
      snprintf(buf, sizeof(buf), "%d°", temp);
      lv_label_set_text(s_temp, buf);
    }

  if (s_light != NULL)
    {
      lv_label_set_text(s_light, light <= 0 ? "低" :
                        (light == 1 ? "中" : "高"));
    }

  if (s_ec != NULL)
    {
      snprintf(buf, sizeof(buf), "%.1f", (float)ec / 10.0f);
      lv_label_set_text(s_ec, buf);
    }
}

