void screen_home_refresh(int health, int moisture, int temp, int light, int ec)
{
  char buf[16];

  if (s_arc != NULL && s_arc_val != NULL)
    {
      if (health < 0)
        {
          health = 0;
        }
      else if (health > 100)
        {
          health = 100;
        }

      lv_arc_set_value(s_arc, health);
      snprintf(buf, sizeof(buf), "%d", health);
      lv_label_set_text(s_arc_val, buf);
    }

  if (s_v_moist != NULL)
    {
      snprintf(buf, sizeof(buf), "%d%%", moisture);
      lv_label_set_text(s_v_moist, buf);
    }

  if (s_v_temp != NULL)
    {
      snprintf(buf, sizeof(buf), "%d°", temp);
      lv_label_set_text(s_v_temp, buf);
    }

  if (s_v_light != NULL)
    {
      lv_label_set_text(s_v_light, light <= 0 ? "低" :
                        (light == 1 ? "中" : "高"));
      lv_obj_set_style_text_color(s_v_light,
                                  lv_color_hex(light <= 0 ? TP_CLR_AMBER :
                                               TP_CLR_GREEN), 0);
    }

  if (s_v_ec != NULL)
    {
      snprintf(buf, sizeof(buf), "%.1f", (float)ec / 10.0f);
      lv_label_set_text(s_v_ec, buf);
    }
}
