void screen_data_refresh(const struct sensor_view_s *view,
                         const struct sensor_history_s *hist)
{
  char buf[24];
  int i;

  if (view == NULL)
    {
      return;
    }

  if (s_moist.value != NULL)
    {
      snprintf(buf, sizeof(buf), "%d", (int)(view->moisture + 0.5f));
      lv_label_set_text(s_moist.value, buf);
      lv_obj_set_style_text_color(s_moist.value,
                                  lv_color_hex(status_color(view->moisture_status)), 0);
    }

  if (s_moist.note != NULL)
    {
      lv_label_set_text(s_moist.note, view->moisture_note[0] != '\0' ?
                        view->moisture_note : "--");
    }

  if (s_temp.value != NULL)
    {
      snprintf(buf, sizeof(buf), "%d", (int)(view->temp + 0.5f));
      lv_label_set_text(s_temp.value, buf);
      lv_obj_set_style_text_color(s_temp.value,
                                  lv_color_hex(status_color(view->temp_status)), 0);
    }

  if (s_temp.note != NULL)
    {
      lv_label_set_text(s_temp.note, view->temp_note[0] != '\0' ?
                        view->temp_note : "--");
    }

  if (s_light.value != NULL)
    {
      lv_label_set_text(s_light.value, view->light_status <= 0 ? "低" :
                        (view->light_status == 1 ? "中" : "高"));
      lv_obj_set_style_text_color(s_light.value,
                                  lv_color_hex(status_color(view->light_status)), 0);
    }

  if (s_light.note != NULL)
    {
      lv_label_set_text(s_light.note, view->light_status <= 0 ? "有点暗" :
                        (view->light_status == 1 ? "刚刚好" : "很充足"));
    }

  if (s_ec.value != NULL)
    {
      snprintf(buf, sizeof(buf), "%.1f", (double)view->ec);
      lv_label_set_text(s_ec.value, buf);
      lv_obj_set_style_text_color(s_ec.value,
                                  lv_color_hex(status_color(view->ec_status)), 0);
    }

  if (s_ec.note != NULL)
    {
      lv_label_set_text(s_ec.note, view->ec_note[0] != '\0' ?
                        view->ec_note : "--");
    }

  if (hist != NULL)
    {
      for (i = 0; i < SENSOR_HISTORY_DAYS; i++)
        {
          int h;

          if (s_bars[i] == NULL)
            {
              continue;
            }

          if (!hist->valid[i])
            {
              lv_obj_set_height(s_bars[i], 4);
              lv_obj_set_style_bg_color(s_bars[i], lv_color_hex(0xe5e7eb), 0);
              continue;
            }

          h = (int)(hist->moisture[i] * 0.3f);
          if (h < 4)
            {
              h = 4;
            }
          else if (h > 30)
            {
              h = 30;
            }

          lv_obj_set_height(s_bars[i], h);
          lv_obj_set_style_bg_color(s_bars[i],
                                    lv_color_hex((i == SENSOR_HISTORY_DAYS - 1) ?
                                                 0x22c55e : 0x60a5fa), 0);
        }
    }
}
