```python
import io

def patch(path, pairs):
    s = io.open(path, encoding='utf-8', errors='replace', newline='').read()
    s = s.replace('\r\n', '\n')
    for i,(old,new) in enumerate(pairs):
        c = s.count(old)
        assert c == 1, 'edit %d count=%d in %s' % (i, c, path)
        s = s.replace(old, new)
    io.open(path,'w',encoding='utf-8',newline='\n').write(s)
    print('patched', path)
```

